package com.school.identity.domain;
import jakarta.persistence.*;import java.util.*;
@Entity @Table(name="users") public class UserAccount { @Id private UUID id; @Column(name="school_id",nullable=false) private UUID schoolId; @Column(name="keycloak_subject") private String keycloakSubject; @Column(nullable=false) private String username; @Column(nullable=false) private String email; @Column(name="display_name",nullable=false) private String displayName; @Column(nullable=false) private String status; @ManyToMany(fetch=FetchType.EAGER) @JoinTable(name="user_roles",joinColumns=@JoinColumn(name="user_id"),inverseJoinColumns=@JoinColumn(name="role_id")) private Set<Role> roles=new LinkedHashSet<>(); protected UserAccount(){} public UserAccount(UUID schoolId,String username,String email,String displayName,String keycloakSubject,Set<Role> roles){this.id=UUID.randomUUID();this.schoolId=schoolId;this.username=username;this.email=email;this.displayName=displayName;this.keycloakSubject=keycloakSubject;this.roles=roles;this.status="ACTIVE";} public void changeRoles(Set<Role> roles){this.roles=roles;} public void changeStatus(String status){this.status=status;} public UUID getId(){return id;}public UUID getSchoolId(){return schoolId;}public String getKeycloakSubject(){return keycloakSubject;}public String getUsername(){return username;}public String getEmail(){return email;}public String getDisplayName(){return displayName;}public String getStatus(){return status;}public Set<Role> getRoles(){return roles;} }
